param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld',[switch]$Check)
# Replays identity, line/excerpt hashes, and selected Core XML. No target execution.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$base=Join-Path $root 'docs/research/rimworld/evidence'
$dllHash='eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'
$engineHash='587a18e18e13acfc7fd8783a44c24c7da0781dadf6b9fb9dd5e2e38a9cdfae78'
function Digest([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function TextDigest([string]$s){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($s))).ToLowerInvariant()}
if((Digest (Join-Path $GameRoot 'Assembly-CSharp.dll')) -ne $dllHash){throw 'Game assembly changed'}
if((Digest (Join-Path $root '../../tools/ilspy/lib/netstandard2.0/ICSharpCode.Decompiler.dll')) -ne $engineHash){throw 'Decompiler changed'}
$groups=[Collections.Generic.HashSet[string]]::new()
function Source([string]$group,[string]$type,[int]$start,[int]$end){
 $m=Get-Content (Join-Path $base "$group-manifest.json") -Raw|ConvertFrom-Json
 if($m.source_sha256 -ne $dllHash -or $m.engine_sha256 -ne $engineHash){throw "Mismatched provenance: $group"}
 $entries=@($m.types|Where-Object type -eq $type)
 if($entries.Count -ne 1){throw "Unknown type: $group/$type"}
 $t=$entries[0];$file=Join-Path $root $t.local_file
 if((Digest $file) -ne $t.sha256){throw "Changed source: $file"}
 $lines=[IO.File]::ReadAllText($file).Split("`n")
 if($lines.Length -ne $t.lines -or $start -lt 1 -or $end -lt $start -or $end -gt $t.lines){throw "Invalid source range: $group/$type"}
 [void]$groups.Add($group)
 [ordered]@{group=$group;type=$type;file=$t.local_file;sha256=$t.sha256;lines=@($start,$end);excerpt_sha256=(TextDigest ($lines[($start-1)..($end-1)] -join "`n"))}
}
$xmlRelative='Data/Core/Defs/ThingDefs_Buildings/Buildings_Furniture.xml'
$xmlFile=Join-Path $GameRoot $xmlRelative
[xml]$doc=[IO.File]::ReadAllText($xmlFile)
$xpath='/Defs/ThingDef[@Name="ShelfBase" or @Name="StorageShelfBase" or @Name="BookcaseBase" or defName="Shelf" or defName="ShelfSmall"]'
$xmlProjection=@(foreach($n in $doc.SelectNodes($xpath)){
 $fields=[ordered]@{}
 foreach($p in @('defName','thingClass','building/storageGroupTag','building/blueprintClass')){
  $field=$n.SelectSingleNode($p);if($field){$fields[$p]=$field.InnerText}
 }
 [ordered]@{name=$n.GetAttribute('Name');parent=$n.GetAttribute('ParentName');abstract=$n.GetAttribute('Abstract');fields=$fields}
})
if($xmlProjection.Count -ne 5){throw 'Unexpected Core storage definitions'}
$xml=@([ordered]@{id='SGX01';file=$xmlRelative;source_sha256=(Digest $xmlFile);xpath=$xpath;projection='Selected identity, immediate parent, class, storage-group tag and blueprint-class fields; not evaluated mod/DLC Def database';nodes=$xmlProjection;nodes_sha256=(TextDigest (($xmlProjection|ConvertTo-Json -Depth 8 -Compress).Replace("`r`n","`n")))})
$claims=@(
 [ordered]@{id='SG01';finding='Link candidates are selected IStorageGroupMember objects with the same StorageGroupTag and Map as the gizmo member; hidden Building_Storage tabs are excluded. The link action is disabled below two candidates. Zone_Stockpile implements storage/slot interfaces but not IStorageGroupMember and exposes copy/paste, not linking. Shelf/ShelfSmall inherit tag Shelf; BookcaseBase uses Bookcase.';xml=@('SGX01');sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 21 32),(Source 'storage-groups' 'RimWorld.StorageGroupUtility' 83 91),(Source 'storage-groups' 'RimWorld.Zone_Stockpile' 7 17),(Source 'storage-groups' 'RimWorld.Zone_Stockpile' 78 89),(Source 'storage-groups' 'RimWorld.IStorageGroupMember' 5 24))},
 [ordered]@{id='SG02';finding='The link action uses tmpMembers[0] as source, retaining its existing group or creating a new group initialized from its effective settings. Only selected compatible members are passed to SetStorageGroup; unselected old-group members are not migrated by this loop. Source order is SelectedObjects enumeration, not guaranteed click order, nearest shelf or an aggregate of filters.';xml=@();sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 25 32),(Source 'storage-groups' 'RimWorld.StorageGroupUtility' 49 81),(Source 'shelf-storage' 'RimWorld.StorageGroup' 107 117))},
 [ordered]@{id='SG03';finding='A linked Building_Storage, Blueprint_Storage and Frame read the StorageGroup settings object rather than synchronized copies. Group parent restrictions come from its first member. CopyFrom copies priority and filter allowances, including allowed defs, special filters, hitpoint and quality ranges; it does not copy the building label or physical contents.';xml=@();sources=@((Source 'logistics' 'RimWorld.Building_Storage' 100 117),(Source 'shelf-storage' 'RimWorld.Blueprint_Storage' 42 54),(Source 'storyteller' 'RimWorld.Frame' 577 591),(Source 'shelf-storage' 'RimWorld.StorageGroup' 135 147),(Source 'preservation' 'RimWorld.StorageSettings' 90 129),(Source 'preservation' 'Verse.ThingFilter' 634 656))},
 [ordered]@{id='SG04';finding='SetStorageGroup switching groups removes the old membership, clears the member reference, copies current old-group settings into local effective settings, then adds the member to the new group and notifies changes. Rejoining the same non-null group is a no-op. Normal helper detachment preserves current shared settings rather than restoring the pre-link local settings.';xml=@();sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 163 184),(Source 'shelf-storage' 'RimWorld.StorageGroup' 119 132))},
 [ordered]@{id='SG05';finding='On ordinary member removal, the manager dissolves groups with zero OR one remaining member; the final member is detached using SetStorageGroup(null), preserving current settings. removeIfEmpty:false bypasses this notification for lifecycle transfers. NewGroup itself can temporarily create an empty group. Post-load null pruning does not call this dissolution path, so this is not proof all malformed singleton/empty saves are normalized.';xml=@();sources=@((Source 'storage-groups' 'Verse.StorageGroupManager' 20 38),(Source 'shelf-storage' 'RimWorld.StorageGroup' 119 132),(Source 'shelf-storage' 'RimWorld.StorageGroup' 165 176))},
 [ordered]@{id='SG06';finding='The explicit Unlink gizmo captures effective group settings, removes the member, clears Group, and copies settings only when the member is Building_Storage. Its derived code is not the general SetStorageGroup helper and does not contain the same copy for Blueprint_Storage/Frame. Multi-selection gizmo dispatch and blueprint/frame unlink effects require runtime validation.';xml=@();sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 92 122),(Source 'storage-groups' 'RimWorld.StorageGroupUtility' 163 184))},
 [ordered]@{id='SG07';finding='Group setting changes notify member ISlotGroupParents. Group Priority changes refresh haul destination priority, all group cells and haul sources. Group HeldThings/CellsList aggregate only members implementing ISlotGroupParent; grouping does not move goods or turn them into a shared physical container.';xml=@();sources=@((Source 'shelf-storage' 'RimWorld.StorageGroup' 53 101),(Source 'shelf-storage' 'RimWorld.StorageGroup' 149 158),(Source 'preservation' 'RimWorld.StorageSettings' 22 54),(Source 'logistics' 'RimWorld.Building_Storage' 119 125))},
 [ordered]@{id='SG08';finding='Uninstall MakeMinified despawns the original building and puts the same instance in InnerThing. Building_Storage.DeSpawn does not remove group membership. Reinstall retrieves that same InnerThing and clears the wrapper before destroying it. Group membership can therefore survive same-map packing/reinstall, and packed members still count; they contribute no occupied slot cells while not Spawned.';xml=@();sources=@((Source 'furniture-reinstall' 'RimWorld.MinifyUtility' 8 31),(Source 'logistics' 'RimWorld.Building_Storage' 83 93),(Source 'logistics' 'RimWorld.Building_Storage' 165 169),(Source 'furniture-reinstall' 'RimWorld.Blueprint_Install' 99 117),(Source 'shelf-storage' 'RimWorld.StorageGroup' 43 45))},
 [ordered]@{id='SG09';finding='Building_Storage.SpawnSetup detaches when the new map differs from the group Map, copying effective group settings locally. This condition concerns spawning the inner building, not merely moving a minified wrapper across maps. Cross-map cargo travel timing is not established by this source path.';xml=@();sources=@((Source 'logistics' 'RimWorld.Building_Storage' 152 163),(Source 'furniture-reinstall' 'RimWorld.MinifiedThing' 21 49))},
 [ordered]@{id='SG10';finding='Building_Storage.Destroy removes membership after base.Destroy; Blueprint_Storage.Destroy removes it before base.Destroy. Destroying a packed wrapper destroys the inner contents. Remaining group members are subject to normal singleton dissolution. Auto-rebuild can replace a destroyed building with a linked blueprint before old-member removal, so destruction is not always a net member-count decrease.';xml=@();sources=@((Source 'logistics' 'RimWorld.Building_Storage' 171 180),(Source 'shelf-storage' 'RimWorld.Blueprint_Storage' 70 75),(Source 'furniture-reinstall' 'RimWorld.MinifiedThing' 229 254),(Source 'energy' 'Verse.Building' 302 328),(Source 'preservation' 'Verse.ThingUtility' 157 164))},
 [ordered]@{id='SG11';finding='Blueprint-to-frame conversion adds the frame to the current group, copies effective settings, then detaches the old blueprint with removeIfEmpty:false. Completed Frame transfers membership and local settings to the new building before detaching itself with the same flag. These lifecycle replacements preserve group identity and shared edits.';xml=@('SGX01');sources=@((Source 'shelf-storage' 'RimWorld.Blueprint_Storage' 92 100),(Source 'storyteller' 'RimWorld.Frame' 326 331),(Source 'storyteller' 'RimWorld.Frame' 128 166))},
 [ordered]@{id='SG12';finding='Group identity is loadID with load reference StorageGroup_<id>, independent of its mutable label and individual building labels. The map serializes storageGroups deeply, manager serializes groups deeply, group serializes member/map references and deep settings. Buildings, blueprints and frames persist their group references alongside local settings; minified wrappers serialize their inner container. PostLoadInit prunes null members, but these paths do not prove full invalid-save repair.';xml=@();sources=@((Source 'energy' 'Verse.Map' 894 898),(Source 'storage-groups' 'Verse.StorageGroupManager' 64 68),(Source 'shelf-storage' 'RimWorld.StorageGroup' 8 33),(Source 'shelf-storage' 'RimWorld.StorageGroup' 160 176),(Source 'logistics' 'RimWorld.Building_Storage' 182 188),(Source 'shelf-storage' 'RimWorld.Blueprint_Storage' 139 144),(Source 'storyteller' 'RimWorld.Frame' 183 191),(Source 'furniture-reinstall' 'RimWorld.MinifiedThing' 175 179))},
 [ordered]@{id='SG13';finding='New groups receive a UniqueIDsManager storage-group ID. Default names search numbered names1..1000 against current-map zone labels, storage-building labels and group labels, then fall back to base X with an error. This generated-name rule is not a demonstrated restriction on manually entered names.';xml=@();sources=@((Source 'storage-groups' 'Verse.StorageGroupManager' 20 25),(Source 'storage-groups' 'Verse.StorageGroupManager' 40 57),(Source 'shelf-storage' 'RimWorld.StorageGroup' 23 33),(Source 'shelf-storage' 'RimWorld.StorageGroup' 107 117))},
 [ordered]@{id='SG14';finding='SelectAllLinked iterates group members and excludes already-selected or destroyed Things. Selection overlays draw only members with DrawConnectionOverlay; finished storage uses Spawned, while storage blueprints use true and frames require a nonempty group tag. Inspector group counts come from all members, including non-spawned members retained by lifecycle.';xml=@();sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 123 161),(Source 'logistics' 'RimWorld.Building_Storage' 35 39),(Source 'logistics' 'RimWorld.Building_Storage' 196 218),(Source 'shelf-storage' 'RimWorld.Blueprint_Storage' 32 38),(Source 'storyteller' 'RimWorld.Frame' 148 166))},
 [ordered]@{id='SG15';finding='Two static edge cases remain runtime-unverified: the AlreadyLinked flag loop reads the gizmo member.Group instead of each enumerated storageGroupMember.Group; Frame.Destroy/FailConstruction lack the symmetric explicit old-frame removal seen in ordinary Blueprint_Storage/Building_Storage destruction. FailConstruction assigns Group directly before calling SetStorageGroup with that same group. Do not infer robust mixed-selection disabling, cancellation cleanup or failed-build recovery from the happy-path transfers.';xml=@();sources=@((Source 'storage-groups' 'RimWorld.StorageGroupUtility' 25 47),(Source 'storage-groups' 'RimWorld.StorageGroupUtility' 83 91),(Source 'storyteller' 'RimWorld.Frame' 193 204),(Source 'storyteller' 'RimWorld.Frame' 408 430),(Source 'storage-groups' 'RimWorld.StorageGroupUtility' 163 184))}
)
$reaFile=Join-Path $base 'shelf-storage-rea-managed.json'
$rea=Get-Content $reaFile -Raw|ConvertFrom-Json
if($rea.subject.digest.sha256 -ne $dllHash -or $rea.normalized_result.summary.module.mvid -ne '8e962ecc-7ac7-42d2-8f3b-1b16cd24d2cd'){throw 'REA identity mismatch'}
$manifestRecords=@(foreach($name in @($groups|Sort-Object)){[ordered]@{file="$name-manifest.json";sha256=(Digest (Join-Path $base "$name-manifest.json"))}})
$e=[ordered]@{
 evidence_id='RW17-STORAGE-GROUPS';version_text=(Get-Content (Join-Path $GameRoot 'Version.txt') -Raw).Trim()
 source_sha256=$dllHash;engine_sha256=$engineHash;kind='Static derived reconstruction and selected original Core XML; target not executed'
 rea=[ordered]@{file='shelf-storage-rea-managed.json';sha256=(Digest $reaFile);evidence_id=$rea.evidence_id;parent_evidence_id=$rea.normalized_result.parent_evidence_id;mvid=$rea.normalized_result.summary.module.mvid}
 manifests=$manifestRecords;xml=$xml;claims=$claims
 limitations=@('Derived C# is not original source; unresolved dependencies are tolerated.','Core XML projections are not a mod-patched effective Def database.','No game execution or real multi-selection, unlink, destruction or load validation is performed by this collector.','SelectedObjects enumeration is not proven to equal player click order.','Explicit unlink on blueprints/frames, mixed-selection disabled-state behavior, failed/cancelled frame cleanup, malformed saves and cross-map transport remain runtime-unverified.','SetStorageGroup itself does not enforce compatible tags/maps; those are constraints of the inspected player linking UI.')
}
$text=($e|ConvertTo-Json -Depth 30).Replace("`r`n","`n")+"`n"
$output=Join-Path $base 'storage-groups-evidence.json'
if($Check){if([IO.File]::ReadAllText($output) -cne $text){throw 'Retained storage-group evidence differs from current local static sources'};"Storage-group source/XML replay verified: $($claims.Count) claims"}
else{[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false));"Collected $($claims.Count) storage-group claims"}
